class Money
  include Comparable

  attr_reader :cents

  def initialize(cents)
    @cents = cents
  end

  def <=>(other)
    return nil unless other.is_a?(Money)
    @cents <=> other.cents
  end

  def ==(other)
    other.is_a?(Money) && @cents == other.cents
  end

  def eql?(other)
    self == other
  end

  def hash
    @cents.hash
  end
end
