class Distance
  attr_reader :meters

  def initialize(meters)
    @meters = meters
  end

  # Handles Distance - Distance and Distance - Integer
  def -(other)
    other_val = other.is_a?(Distance) ? other.meters : other
    Distance.new(@meters - other_val)
  end

  # Handles Integer - Distance
  # This is called when the left side is an Integer and the right side is a Distance
  def coerce(other)
    [other, self]
  end

  def ==(other)
    return false unless other.is_a?(Distance)
    @meters == other.meters
  end
end
