class Registry
  def initialize
    # We use an Array to maintain the insertion order for #to_a.
    # We use a Set (or just check identity) to ensure uniqueness based on object_id.
    @storage = []
    @object_ids = {}
  end

  # Adds obj to the registry. 
  # If the exact same object (same object_id) is already present, do nothing.
  # If a different object that is == to an existing one is passed, it is added.
  def register(obj)
    unless @object_ids.key?(obj.object_id)
      @storage << obj
      @object_ids[obj.object_id] = true
    end
    self
  end

  # Returns true only if the exact same object instance has been registered.
  def registered?(obj)
    @object_ids.key?(obj.object_id)
  end

  # Returns the current number of registered objects.
  def size
    @storage.size
  end

  # Returns the registered objects in the order they were first registered.
  def to_a
    @storage.dup
  end
end
